export const exportUserDataResponseGoalsItemEndDateRegExp = new RegExp('^\\d{4}-\\d{2}-\\d{2}$');


export const ExportUserDataResponse = zod.object({
  "profile": zod.object({
  "id": zod.string().uuid(),
  "name": zod.string(),
  "email": zod.string().email(),
  "age": zod.number().int().nullable(),
  "gender": zod.string(),
  "heightCm": zod.number().nullable(),
  "weightKg": zod.number().nullable(),
  "activityLevel": zod.enum(['sedentary', 'light', 'moderate', 'active', 'very_active']),
  "themePreference": zod.enum(['light', 'dark']),
  "onboardingComplete": zod.boolean(),
  "goals": zod.object({
  "waterMl": zod.number().int(),
  "steps": zod.number().int(),
  "exerciseMinutes": zod.number().int(),
  "sleepHours": zod.number()
})
}),
  "records": zod.array(zod.object({
  "id": zod.string().uuid(),
  "date": zod.string().regex(exportUserDataResponseRecordsItemDateRegExp),
  "waterMl": zod.number().int(),
  "steps": zod.number().int(),
  "exerciseMinutes": zod.number().int(),
  "sleepHours": zod.number(),
  "sleepQuality": zod.number().int().nullable(),
  "heartRateBpm": zod.number().int().nullable(),
  "weightKg": zod.number().nullable(),
  "caloriesConsumed": zod.number().int(),
  "proteinGrams": zod.number().nullable(),
  "carbsGrams": zod.number().nullable(),
  "fatGrams": zod.number().nullable(),
  "mood": zod.union([zod.literal('very_sad'),zod.literal('sad'),zod.literal('neutral'),zod.literal('happy'),zod.literal('very_happy'),zod.literal(null)]).nullable(),
  "stressLevel": zod.union([zod.literal('low'),zod.literal('medium'),zod.literal('high'),zod.literal('extreme'),zod.literal(null)]).nullable(),
  "wellnessScore": zod.number().int(),
  "notes": zod.string().nullable()
})),
  "goals": zod.array(zod.object({
  "id": zod.string().uuid(),
  "goalType": zod.enum(['water_ml', 'steps', 'exercise_min', 'sleep_hrs', 'weight_kg', 'calories_kcal']),
  "targetValue": zod.number(),
  "currentValue": zod.number(),
  "startDate": zod.string().regex(exportUserDataResponseGoalsItemStartDateRegExp),
  "endDate": zod.string().regex(exportUserDataResponseGoalsItemEndDateRegExp).nullable(),
  "status": zod.enum(['active', 'completed', 'abandoned'])
})),
  "reminders": zod.array(zod.object({
  "id": zod.string().uuid(),
  "title": zod.string(),
  "category": zod.enum(['water', 'exercise', 'sleep', 'medication', 'break']),
  "timeOfDay": zod.string(),
  "frequency": zod.enum(['daily', 'weekdays', 'weekends']),
  "isEnabled": zod.boolean()
}))
})


/**
 * @summary Permanently delete the account and its health data
 */
export const DeleteAccountResponse = zod.object({
  "message": zod.string()
})


